function Total([object[]]$Values) {
    $sum=0L
    foreach($value in $Values){if($value -isnot [long] -and $value -isnot [int]){throw 'noninteger counter'};if($value -lt 0){throw 'negative counter'};$sum += [long]$value}
    return $sum
}
function Read-Counts([string]$Stdout) {
    $lines=$Stdout.Replace("`r`n","`n").Split("`n")
    if($lines.Count -ne 3 -or $lines[2] -cne ''){throw 'exactly two stdout JSON lines required'}
    return [pscustomobject]@{plain_text=$lines[0]+"`n";plain=($lines[0]|ConvertFrom-Json);counts_text=$lines[1];counts=($lines[1]|ConvertFrom-Json)}
}
function Assert-Counts($Counts,$Schedule) {
    if(!$Counts.operation_counts -or $Counts.overflow -or !$Counts.phase_restored -or $Counts.counter_state_bytes -ne 14360 -or $Counts.stages.Count -ne 4){throw 'counter state failure'}
    for($stage=0;$stage -lt 4;$stage++){
        if($Counts.stages[$stage].stage -cne @('light','active','replay','reference')[$stage] -or $Counts.stages[$stage].classes.Count -ne 7){throw 'stage/class schema'}
        for($class=0;$class -lt 7;$class++){
            $row=$Counts.stages[$stage].classes[$class]
            if($row.bayes.Count -ne 4 -or $row.light_depth.Count -ne 17 -or $row.heavy_kt.Count -ne 4 -or $row.ratio_flags.Count -ne 32){throw 'counter array schema'}
            $expected=if($stage -eq 0){[long]$Schedule.events[$class]}elseif($stage -eq 1){[long]$Schedule.active_events[$class]}elseif($stage -eq 2){[long]$Schedule.replayed[$class]}else{0L}
            if((Total $row.bayes) -ne $expected){throw 'Bayes calls versus schedule mismatch'}
            if($stage -eq 0){
                if((Total $row.light_depth) -ne $expected -or $row.light_nodes -ne 17*$expected -or $row.light_probes -lt $expected -or $row.light_probes -gt 16*$expected){throw 'light histogram/nodes/probes mismatch'}
                if($row.heavy_predicts -ne 0 -or $row.heavy_updates -ne 0 -or (Total $row.heavy_kt) -ne 0 -or $row.heavy_mixtures -ne 0 -or $row.heavy_nodes -ne 0 -or $row.ratio_wrapper -ne 0 -or (Total $row.ratio_flags) -ne 0){throw 'heavy leaked into light'}
            }else{
                if((Total $row.light_depth) -ne 0 -or $row.light_probes -ne 0 -or $row.light_nodes -ne 0){throw 'light leaked into heavy'}
                if($row.heavy_predicts -ne $expected -or $row.heavy_updates -ne $expected -or (Total $row.heavy_kt) -ne 17*$expected -or $row.heavy_kt[0] -ne 0 -or $row.heavy_mixtures -ne 16*$expected -or $row.heavy_nodes -ne 17*$expected -or $row.ratio_wrapper -ne 33*$expected -or (Total $row.ratio_flags) -ne $row.ratio_wrapper+$row.heavy_kt[3]){throw 'heavy operations mismatch'}
                for($flag=0;$flag -lt 32;$flag++){if($flag -notin @(1,2,6,8,18,22) -and $row.ratio_flags[$flag] -ne 0){throw 'unexpected ratio flags'}}
                if($row.ratio_flags[18] -ne 0 -or $row.ratio_flags[22] -ne 0){throw 'certificate fallback in normal codec'}
            }
        }
    }
}

